import{_ as i,o as t,c as r,a5 as s}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/profile/3-3-1-view-user-profile/report3_spec.md","filePath":"feature/profile/3-3-1-view-user-profile/report3_spec.md"}'),o={name:"feature/profile/3-3-1-view-user-profile/report3_spec.md"};function n(l,e,a,p,d,c){return t(),r("div",null,[...e[0]||(e[0]=[s("<p><strong>3.3.1 View User Profile</strong></p><p><strong>Function Trigger</strong></p><p>Begins when a signed-in user opens the Profile screen at /profile.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Any authenticated user (role USER); a user reads only their own profile.</li><li><strong>Purpose</strong>: Display the personal information the system holds for the signed-in user, so the user can verify it.</li><li><strong>Interface</strong>: The Profile screen at /profile, a single page combining the read-only view and the edit form. Edit toggles the section into edit mode (see FR 3.3.2). In view mode every field is text-only.</li><li><strong>Data Processing</strong>: The system resolves the caller&#39;s identity from the access token only, loads the matching user record, resolves the system role, resolves the current workspace, and derives timezone and notification preferences from the preferences data on the user record. No data is modified.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Profile Screen (/profile, view mode):</p><ul><li>Header: page title &quot;Profile&quot;.</li><li>Top card: avatar image (or default initials avatar), full name, email, a &quot;Verified&quot; badge, and an Edit button.</li><li>Two-column grid: system role, phone number (with a change/add-phone link), member-since date, last-login date, job title (professionalTitle), working language, timezone, bio, portfolio URLs (list of links) — each showing an empty-state placeholder when not set.</li><li>Side panel: Danger Zone card with a Deactivate Account button (separate flow, not part of this FR).</li><li>Buttons: Edit — switches the profile card into edit mode (FR 3.3.2).</li><li>Footer: none.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: None — identity is derived from the access token; the caller cannot supply another user&#39;s identifier.</li><li><strong>Input optional</strong>: None.</li><li><strong>System data</strong>: users (userId, email, fullName, avatarUrl, phone, professionalTitle, bio, portfolioUrls, workingLanguage, preferences JSON, createdAt); user_system_roles (system role); workspace_members (workspaceId).</li><li><strong>Output</strong>: userId, email, fullName, avatarUrl, phone, role, workspaceId, professionalTitle, bio, portfolioUrls, workingLanguage, timezone, notificationPreferences, createdAt.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-18</strong>: /users/me resolves identity from the JWT principal only, so a user can never read another user&#39;s profile.</li><li>role defaults to USER when no role record exists; workspaceId falls back to the user&#39;s first active workspace membership when the token carries none.</li><li>timezone and notificationPreferences have no dedicated columns; both live inside the JSON preferences field.</li><li>avatarUrl is empty when no avatar was ever uploaded; a default initials avatar is shown — not an error.</li><li>professionalTitle, bio, and workingLanguage are plain nullable columns; portfolioUrls is a JSON string deserialized to a list (unparsable or blank returns an empty list, never an error).</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Empty required fields → not applicable (no request body).</li><li>Missing, expired, or invalid access token → Display: <strong>MSG22</strong>.</li><li>User record no longer exists → Display: <strong>MSG38</strong>.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>The signed-in user opens /profile.</li><li>The application requests the signed-in user&#39;s own profile.</li><li>The system resolves the caller&#39;s identity from the access token and loads the matching user record.</li><li>The system resolves the system role, applying the default when no role record exists.</li><li>The system resolves the current workspace, falling back to the first active workspace membership when needed.</li><li>The system derives timezone and notificationPreferences from the stored preferences data.</li><li>The system returns the complete profile field set.</li><li>The application renders the read-only profile card, showing a default initials avatar when none exists.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>3.a1: Missing, expired, or invalid access token, the system displays <strong>MSG22</strong>. 3.a2: The user signs in again at /login (3.2.2).</li><li>3.b1: The user record no longer exists, the system displays <strong>MSG38</strong>. 3.b2: The user is signed out and returned to /login.</li><li>8.a1: No avatar has ever been set, avatarUrl is empty. 8.a2: The application shows a default initials avatar.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>The signed-in user&#39;s profile is displayed with the values currently stored in the system.</li><li>No data is changed; the operation is read-only.</li></ul>",14)])])}const h=i(o,[["render",n]]);export{g as __pageData,h as default};
